const mode = ($json && $json.mode) || 'DRY_RUN';
const provider = ($json && $json.provider) || 'NOT_CONFIGURED';
const message_variants = ($json && $json.message_variants) || {};
return [{ json: { mode, provider, message_variants } }];

const approvedItems = $('Read Approved Outreach').all();
const outreachItems = $('Read Outreach Log').all();
const modeRef = $('Initialize Execution Mode');
const modeItem = (modeRef && modeRef.item) || {};

const approvedRows = approvedItems.map((item) => (item && item.json) || {});
const outreachRows = outreachItems.map((item) => (item && item.json) || {});

const normalize = (value) => (value === undefined || value === null ? '' : String(value).trim());

const READY = 'READY';
const NOT_READY = 'NOT_READY';
const BLOCKED = 'BLOCKED';
const EMAIL = 'email';
const CALL = 'call';
const NONE = 'none';
const MIN_PHONE_DIGITS = 7;

const countDigits = (value) => String(value).replace(/\D+/g, '').length;

const parseScore = (value) => {
  const n = Number(String(value));
  return Number.isFinite(n) ? n : 0;
};

const isVerifiedEmail = (record) => normalize(record.email_verified) !== '';
const isUsablePhone = (record) => {
  const phone = normalize(record.phone);
  return phone !== '' && countDigits(phone) >= MIN_PHONE_DIGITS;
};
const isSuppressed = (record) => normalize(record.outreach_status) === 'suppressed';

const readinessFor = (record) => {
  if (isSuppressed(record)) return { available_channel: NONE, readiness_status: BLOCKED, reason: 'suppressed' };
  if (isVerifiedEmail(record)) return { available_channel: EMAIL, readiness_status: READY, reason: 'verified email available' };
  if (isUsablePhone(record)) return { available_channel: CALL, readiness_status: READY, reason: 'phone available' };
  return { available_channel: NONE, readiness_status: NOT_READY, reason: 'no available channel' };
};

const buildApprovalIndex = (rows) => {
  const index = new Map();
  const malformed = [];
  const duplicates = [];
  rows.forEach((row, i) => {
    const leadId = normalize(row.lead_id);
    const approvedAt = normalize(row.approved_at);
    if (!leadId || !approvedAt) {
      malformed.push({ lead_id: leadId, business_name: normalize(row.business_name), outreach_status: normalize(row.outreach_status), approved_at: approvedAt });
      return;
    }
    if (index.has(leadId)) {
      duplicates.push({ lead_id: leadId, business_name: normalize(row.business_name), approved_at: approvedAt });
      return;
    }
    index.set(leadId, { row: Object.assign({}, row), index: i, leadId, approvedAt });
  });
  return { index, malformed, duplicates };
};

const buildHistoryIndex = (rows) => {
  const malformed = [];
  const byLead = new Map();
  rows.forEach((row, i) => {
    const leadId = normalize(row.lead_id);
    const sentAt = normalize(row.sent_at);
    if (!leadId || !sentAt) {
      malformed.push({ lead_id: leadId, outreach_id: normalize(row.outreach_id), business_name: normalize(row.business_name) });
      return;
    }
    if (!byLead.has(leadId)) byLead.set(leadId, []);
    byLead.get(leadId).push({ leadId, sentAt, channel: normalize(row.channel), outcome: normalize(row.outcome), outreach_id: normalize(row.outreach_id), rowIndex: i });
  });
  for (const records of byLead.values()) {
    records.sort((a, b) => (a.sentAt < b.sentAt ? -1 : a.sentAt > b.sentAt ? 1 : a.rowIndex - b.rowIndex));
  }
  return { index: byLead, malformed };
};

const buildHistory = (records) => {
  if (!records || records.length === 0) return { outreach_count: 0, last_outreach_at: '', latest_channel: '', latest_outcome: '' };
  const latest = records[records.length - 1];
  return { outreach_count: records.length, last_outreach_at: latest.sentAt, latest_channel: latest.channel, latest_outcome: latest.outcome };
};

const findOrphans = (historyIndex, approvalIndex) => {
  const orphans = [];
  for (const [leadId, records] of historyIndex) {
    if (approvalIndex.has(leadId)) continue;
    for (const record of records) {
      orphans.push({ lead_id: record.leadId, outreach_id: record.outreach_id, sent_at: record.sentAt, channel: record.channel });
    }
  }
  orphans.sort((a, b) => (a.lead_id < b.lead_id ? -1 : a.lead_id > b.lead_id ? 1 : a.sent_at < b.sent_at ? -1 : 1));
  return orphans;
};

const sortLeads = (a, b) => {
  const scoreDiff = parseScore(b.row.lead_score) - parseScore(a.row.lead_score);
  if (scoreDiff !== 0) return scoreDiff;
  if (a.approvedAt < b.approvedAt) return -1;
  if (a.approvedAt > b.approvedAt) return 1;
  return a.leadId < b.leadId ? -1 : a.leadId > b.leadId ? 1 : 0;
};

const buildQueue = (approvalIndex, historyIndex, queuedAt) => {
  const sortedForQueue = [...approvalIndex.values()].sort(sortLeads);
  return sortedForQueue.map((entry, i) => {
    const row = entry.row;
    const readiness = readinessFor(row);
    const history = buildHistory(historyIndex.get(entry.leadId));
    return {
      queue_id: entry.leadId,
      lead_id: entry.leadId,
      business_name: normalize(row.business_name),
      niche: normalize(row.niche),
      city: normalize(row.city),
      state: normalize(row.state),
      country: normalize(row.country),
      lead_score: normalize(row.lead_score),
      qualification_status: normalize(row.qualification_status),
      available_channel: readiness.available_channel,
      readiness_status: readiness.readiness_status,
      priority: i + 1,
      approved_at: entry.approvedAt,
      queued_at: queuedAt,
      last_outreach_at: history.last_outreach_at,
      outreach_count: history.outreach_count,
      latest_channel: history.latest_channel,
      latest_outcome: history.latest_outcome,
      enrichment_required: readiness.available_channel === NONE && readiness.readiness_status === NOT_READY,
      reason: readiness.reason,
      notes: normalize(row.notes),
    };
  });
};

const sortExceptionsList = (a, b) => {
  const ka = [a.exception_type || '', a.lead_id || '', a.details || ''];
  const kb = [b.exception_type || '', b.lead_id || '', b.details || ''];
  for (let i = 0; i < ka.length; i += 1) {
    if (ka[i] < kb[i]) return -1;
    if (ka[i] > kb[i]) return 1;
  }
  return 0;
};

const runAt = new Date().toISOString();
const runId = 'EXECUTION-' + runAt.replace(/[^\d]/g, '').slice(0, 14);

let approvedError = '';
let outreachError = '';
if (approvedItems.length === 1 && approvedItems[0].json && approvedItems[0].json._source_read_error) approvedError = String(approvedItems[0].json._source_read_error);
if (outreachItems.length === 1 && outreachItems[0].json && outreachItems[0].json._source_read_error) outreachError = String(outreachItems[0].json._source_read_error);

const MODE = normalize(modeItem.mode) || 'DRY_RUN';
const RUN_MODE = MODE === 'REAL' ? 'REAL' : 'DRY_RUN';
const PROVIDER_MODE = normalize(modeItem.provider) || 'NOT_CONFIGURED';
const providerConfigured = PROVIDER_MODE === 'SUCCESS' || PROVIDER_MODE === 'FAILURE';
const message_variants = (modeItem.message_variants) || {};

const EXECUTION_STATUS = {
  SKIPPED: 'EXECUTION_SKIPPED',
  REJECTED: 'EXECUTION_REJECTED',
  FAILED: 'EXECUTION_FAILED',
  SUCCEEDED: 'EXECUTION_SUCCEEDED',
  DUPLICATE_SUPPRESSED: 'DUPLICATE_SUPPRESSED',
};

const outreachIdFor = (leadId, channel) => 'EX-' + normalize(leadId) + '-' + (normalize(channel) || '?');

const buildSentIndex = (rows) => {
  const index = new Map();
  rows.forEach((obj) => {
    const row = obj || {};
    const leadId = normalize(row.lead_id);
    const sentAt = normalize(row.sent_at);
    if (!leadId || !sentAt) return;
    const channel = normalize(row.channel);
    index.set(leadId + '\u0000' + channel, { lead_id: leadId, channel, sent_at: sentAt });
  });
  return index;
};

const notConfiguredError = (msg) => ({ success: false, error_code: 'PROVIDER_NOT_CONFIGURED', error_message: msg || 'No real provider adapter is configured; execution is refused. This is the safe default — nothing was sent.' });

const mockExecute = (channel, payload) => {
  if (PROVIDER_MODE === 'FAILURE') return { success: false, error_code: 'MOCK_PROVIDER_FAILURE', error_message: 'mock provider returned failure mode; no message was sent' };
  if (PROVIDER_MODE === 'NOT_CONFIGURED') return notConfiguredError();
  return { success: true, provider_status: 'accepted', provider_message_id: 'mock:' + runId };
};

const validatePayload = (item) => {
  if (item.available_channel === EMAIL) {
    if (!item.email || !item.message_variant) return { ok: false, detail: 'email channel requires a non-empty email and an explicit message_variant' };
  } else if (item.available_channel === CALL) {
    if (!item.phone) return { ok: false, detail: 'call channel requires a non-empty phone' };
  }
  return { ok: true, detail: '' };
};

const buildPayload = (item) => {
  const payload = { execution_id: runId, outreach_id: item.outreach_id, lead_id: item.lead_id, business_name: item.business_name, contact_name: item.contact_name, channel: item.available_channel, message_variant: item.message_variant };
  if (item.available_channel === EMAIL) payload.email = item.email;
  if (item.available_channel === CALL) payload.phone = item.phone;
  return payload;
};

const resultView = (r) => ({ success: Boolean(r && r.success), provider_status: (r && r.provider_status) || '', provider_message_id: (r && r.provider_message_id) || '', error_code: (r && r.error_code) || '', error_message: (r && r.error_message) || '' });

const buildLogRow = (item) => ({
  outreach_id: item.outreach_id,
  lead_id: item.lead_id,
  business_name: item.business_name,
  contact_name: item.contact_name,
  channel: item.available_channel,
  email: item.available_channel === EMAIL ? item.email : '',
  phone: item.available_channel === CALL ? item.phone : '',
  message_variant: item.message_variant,
  sent_at: runAt,
  follow_up_date: '',
  follow_up_number: '',
  reply_status: '',
  reply_date: '',
  pain_admitted: '',
  call_booked: '',
  call_date: '',
  paid_pilot_interest: '',
  objection: '',
  outcome: '',
  notes: '',
});

const gate = (item, index) => {
  if (item.readiness_status === BLOCKED) return { ok: false, status: EXECUTION_STATUS.SKIPPED, reason: 'BLOCKED', detail: 'blocked: suppressed lead; no execution' };
  if (item.readiness_status === NOT_READY) return { ok: false, status: EXECUTION_STATUS.SKIPPED, reason: 'NOT_READY', detail: 'not ready: ' + (item.reason || 'no available channel') };
  if (item.available_channel !== EMAIL && item.available_channel !== CALL) return { ok: false, status: EXECUTION_STATUS.REJECTED, reason: 'NO_CHANNEL', detail: 'queue record has no supported channel' };
  if (index.has(item.lead_id + '\u0000' + item.available_channel)) return { ok: false, status: EXECUTION_STATUS.DUPLICATE_SUPPRESSED, reason: 'DUPLICATE', detail: 'existing committed outreach log row for lead_id+channel; suppressed' };
  return { ok: true };
};

const resultCard = (item, partial) => Object.assign({ lead_id: item.lead_id, outreach_id: item.outreach_id, business_name: item.business_name, channel: item.available_channel, readiness_status: item.readiness_status, status: '', reason: '', detail: '', payload: null, provider_call: null, sent_at: '' }, partial);

if (approvedError || outreachError) {
  const nullMetrics = { approved_total: null, queue_total: null, ready_candidates: null, executed_attempted: null, executed_succeeded: null, executed_failed: null, executed_skipped: null, executed_rejected: null, duplicate_suppressed: null, log_rows_written: null, provider_calls: null };
  return [
    { json: Object.assign({ run_id: runId, status: 'EXECUTION_INCOMPLETE', run_at: runAt, mode: RUN_MODE, provider: PROVIDER_MODE, provider_configured: providerConfigured }, nullMetrics, { results: [], log_rows: [], exceptions: [], sources: { approved_ok: !approvedError, outreach_ok: !outreachError, approved_read_error: approvedError, outreach_read_error: outreachError } }) },
    { json: { run_id: runId, log_rows: [], log_rows_written: 0 } },
  ];
}

const approved = buildApprovalIndex(approvedRows);
const history = buildHistoryIndex(outreachRows);
const orphans = findOrphans(history.index, approved.index);
const queue = buildQueue(approved.index, history.index, runAt);

const exceptionRows = [];
for (const o of orphans) exceptionRows.push({ run_id: runId, lead_id: o.lead_id, outreach_id: o.outreach_id, exception_type: 'OUTREACH_WITHOUT_APPROVAL', severity: 'ERROR', details: 'Outreach Log has a record but no matching Approved Outreach row' });
for (const m of history.malformed) exceptionRows.push({ run_id: runId, lead_id: m.lead_id, outreach_id: m.outreach_id, exception_type: 'MALFORMED_OUTREACH', severity: 'ERROR', details: 'outreach record missing lead_id or sent_at' });
for (const m of approved.malformed) exceptionRows.push({ run_id: runId, lead_id: m.lead_id, business_name: m.business_name, approved_status: m.outreach_status, exception_type: 'MALFORMED_APPROVAL', severity: 'ERROR', details: 'approved row missing lead_id or approved_at' });
exceptionRows.sort(sortExceptionsList);

const byApprovedLead = new Map();
approvedRows.forEach((obj) => {
  const row = obj || {};
  const leadId = normalize(row.lead_id);
  if (!leadId || byApprovedLead.has(leadId)) return;
  byApprovedLead.set(leadId, row);
});

const merged = queue.map((q) => {
  const a = byApprovedLead.get(q.lead_id) || {};
  const item = Object.assign({}, q, {
    email: normalize(a.email),
    phone: normalize(a.phone),
    contact_name: normalize(a.contact_name),
    message_variant: message_variants[q.lead_id] !== undefined ? normalize(message_variants[q.lead_id]) : '',
  });
  item.outreach_id = outreachIdFor(item.lead_id, item.available_channel);
  return item;
});

const sentIndex = buildSentIndex(outreachRows);
let attempts = 0;
const results = [];
const logRows = [];

for (const item of merged) {
  const g = gate(item, sentIndex);
  if (!g.ok) { results.push(resultCard(item, { status: g.status, reason: g.reason, detail: g.detail })); continue; }
  const check = validatePayload(item);
  if (!check.ok) { results.push(resultCard(item, { status: EXECUTION_STATUS.REJECTED, reason: 'INVALID_PAYLOAD', detail: check.detail, payload: buildPayload(item) })); continue; }
  const payload = buildPayload(item);
  if (RUN_MODE === 'DRY_RUN') { results.push(resultCard(item, { status: EXECUTION_STATUS.SKIPPED, reason: 'DRY_RUN', detail: 'dry run: provider not called, no Outreach Log write', payload })); continue; }
  attempts += 1;
  const view = resultView(mockExecute(item.available_channel, payload));
  if (view.success) {
    const row = buildLogRow(item);
    logRows.push(row);
    results.push(resultCard(item, { status: EXECUTION_STATUS.SUCCEEDED, reason: 'EXECUTION_SUCCESS', detail: 'provider confirmed the attempt; Outreach Log row staged', payload, provider_call: view, sent_at: runAt }));
  } else {
    const notConfigured = view.error_code === 'PROVIDER_NOT_CONFIGURED';
    results.push(resultCard(item, { status: EXECUTION_STATUS.FAILED, reason: notConfigured ? 'PROVIDER_NOT_CONFIGURED' : 'PROVIDER_FAILURE', detail: notConfigured ? 'provider is not configured; execution refused, nothing was sent' : 'provider reported failure (' + (view.error_code || 'unknown') + '); nothing was sent', payload, provider_call: view }));
  }
}

const outputs = {
  run_id: runId,
  status: 'COMPLETED',
  run_at: runAt,
  mode: RUN_MODE,
  provider: PROVIDER_MODE,
  provider_configured: providerConfigured,
  approved_total: approvedRows.length,
  queue_total: queue.length,
  ready_candidates: queue.filter((q) => q.readiness_status === READY).length,
  executed_attempted: attempts,
  executed_succeeded: results.filter((r) => r.status === EXECUTION_STATUS.SUCCEEDED).length,
  executed_failed: results.filter((r) => r.status === EXECUTION_STATUS.FAILED).length,
  executed_skipped: results.filter((r) => r.status === EXECUTION_STATUS.SKIPPED).length,
  executed_rejected: results.filter((r) => r.status === EXECUTION_STATUS.REJECTED).length,
  duplicate_suppressed: results.filter((r) => r.status === EXECUTION_STATUS.DUPLICATE_SUPPRESSED).length,
  log_rows_written: logRows.length,
  provider_calls: attempts,
  results,
  log_rows: logRows,
  exceptions: exceptionRows,
  sources: { approved_ok: true, outreach_ok: true, approved_read_error: '', outreach_read_error: '' },
};

return [
  { json: outputs },
  { json: { run_id: runId, log_rows: logRows, log_rows_written: logRows.length } },
];

const input = $input.first().json || {};
const logRows = Array.isArray(input.log_rows) ? input.log_rows : [];
const out = ["outreach_id","lead_id","business_name","contact_name","channel","email","phone","message_variant","sent_at","follow_up_date","follow_up_number","reply_status","reply_date","pain_admitted","call_booked","call_date","paid_pilot_interest","objection","outcome","notes"];
return logRows.map((row) => {
  const item = {};
  for (const c of out) item[c] = row[c] === undefined || row[c] === null ? '' : String(row[c]);
  return { json: item };
});
